def set_up(total: float, each: float) -> str:
    """Say the problem as a sentence before you write any symbols on it."""
    count = total / each
    if each <= 0 or count != int(count):
        raise ValueError(f'{each:g} does not divide {total:g} evenly, so this page is not set up yet')
    return f'{count:g} groups of {each:g} make {total:g}'


def read_it_back(total: float, each: float) -> str:
    return f'{total:g} split into groups of {each:g} is {int(total / each):d} groups, and no symbols were needed to say it.'
